import { type } from "arktype";

/**
 * `State` - the machine's state, modelled as a true discriminated union
 * keyed by the `status` literal so that ArkType can resolve each branch
 * deterministically (rather than relying on a plain `or` chain of differently
 * morphed objects).
 *
 * Branches:
 *   - Idle:    { status: "idle" }
 *   - Loading: { status: "loading", startedAt: non-negative integer }
 *   - Success: { status: "success", data: unknown, fetchedAt: non-negative integer }
 *   - Failure: { status: "failure", code: integer in [400, 599], reason: string 1..200 }
 */
export const State = type.or(
  { status: '"idle"' },
  {
    status: '"loading"',
    startedAt: "number.integer >= 0",
  },
  {
    status: '"success"',
    data: "unknown",
    fetchedAt: "number.integer >= 0",
  },
  {
    status: '"failure"',
    code: "400 <= number.integer <= 599",
    reason: "1 <= string <= 200",
  },
);

/**
 * `Event` - the incoming event, modelled as a true discriminated union
 * keyed by the `type` literal.
 *
 * Branches:
 *   - Start:   { type: "start", at: number }
 *   - Resolve: { type: "resolve", data: unknown, at: number }
 *   - Reject:  { type: "reject", code: number, reason: string, at: number }
 *   - Reset:   { type: "reset" }
 */
export const Event = type.or(
  {
    type: '"start"',
    at: "number",
  },
  {
    type: '"resolve"',
    data: "unknown",
    at: "number",
  },
  {
    type: '"reject"',
    code: "number",
    reason: "string",
    at: "number",
  },
  {
    type: '"reset"',
  },
);

export type State = typeof State.infer;
export type Event = typeof Event.infer;

import { type } from "arktype";
import { State, type State as StateT, type Event as EventT } from "./schemas.js";

/**
 * Pure transition logic. Returns the *intended* next state for a valid
 * (state, event) pair, or the input state unchanged for any pair not
 * listed in the spec.
 *
 * The runtime validation of inputs/outputs lives in `transition` (below),
 * not here: this function is a plain implementation that *must* be invoked
 * through the validated wrapper so that malformed states/events are caught
 * at the boundary.
 */
export function transitionImpl(state: StateT, event: EventT): StateT {
  // `Reset` always returns `Idle`, irrespective of the current state.
  if (event.type === "reset") {
    return { status: "idle" };
  }

  if (state.status === "idle" && event.type === "start") {
    return {
      status: "loading",
      startedAt: Math.trunc(event.at),
    };
  }

  if (state.status === "loading" && event.type === "resolve") {
    return {
      status: "success",
      data: event.data,
      fetchedAt: Math.trunc(event.at),
    };
  }

  if (state.status === "loading" && event.type === "reject") {
    return {
      status: "failure",
      code: event.code,
      reason: event.reason,
    };
  }

  // Every other (state, event) pairing leaves the state unchanged.
  return state;
}

/**
 * `transition` - the public, runtime-validated transition function.
 *
 * Inputs are checked against `State` and `Event`, and the output is checked
 * against `State`. The implementation delegates to `transitionImpl`.
 *
 * Wrapped with `type.fn` so the contract is fully introspectable (`.params`,
 * `.returns`, `.expression`). `type.fn` throws a `TraversalError` whose
 * `.arkErrors` field carries the underlying `ArkErrors` when validation
 * fails; callers (e.g. `cli.ts`) translate that into the required stdout
 * format.
 */
export const transition = type.fn(State, Event, ":", State)(transitionImpl);

import { readFileSync } from "node:fs";
import { stdin } from "node:process";
import { ArkErrors } from "arktype";
import { transition } from "./src/transition.js";

/**
 * The stdin document shape:
 *   { "initial": <State>, "events": [<Event>, ...] }
 *
 * We accept any JSON-shaped object from `unknown` and narrow it through
 * ArkType so a malformed envelope produces a clear `INVALID: ...` line
 * rather than a TypeError.
 */
interface ReplayRequest {
  initial: unknown;
  events: unknown[];
}

function readStdin(): string {
  // Read everything available on stdin synchronously. tsx / node will
  // deliver EOF after the consumer closes the pipe, so `readFileSync`
  // against `/dev/stdin` is sufficient.
  return readFileSync(stdin.fd, "utf8");
}

function toInvalidLine(err: unknown): string {
  if (err instanceof ArkErrors) {
    return `INVALID: ${err.summary}`;
  }
  // `type.fn` throws a `TraversalError` whose `.arkErrors` field carries
  // the underlying `ArkErrors` from validation. Pull `summary` out so the
  // message is human-readable and matches the ArkErrors-style failure
  // described in the task.
  if (err && typeof err === "object" && "arkErrors" in err) {
    const inner = (err as { arkErrors: unknown }).arkErrors;
    if (inner instanceof ArkErrors) {
      return `INVALID: ${inner.summary}`;
    }
  }
  if (err instanceof Error) {
    return `INVALID: ${err.message}`;
  }
  return `INVALID: ${String(err)}`;
}

function main(): void {
  let raw: string;
  try {
    raw = readStdin();
  } catch (e) {
    process.stdout.write(toInvalidLine(e) + "\n");
    return;
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    process.stdout.write(toInvalidLine(e) + "\n");
    return;
  }

  if (!parsed || typeof parsed !== "object") {
    process.stdout.write(`INVALID: input must be a JSON object\n`);
    return;
  }

  const req = parsed as Partial<ReplayRequest>;
  if (!("initial" in req) || !("events" in req)) {
    process.stdout.write(
      `INVALID: input must contain both "initial" and "events"\n`,
    );
    return;
  }
  if (!Array.isArray(req.events)) {
    process.stdout.write(`INVALID: "events" must be an array\n`);
    return;
  }

  try {
    let current = transition.initial(req.initial as never);
    for (const ev of req.events) {
      current = transition(current, ev as never);
    }
    process.stdout.write(`VALID\n${JSON.stringify(current)}\n`);
  } catch (e) {
    process.stdout.write(toInvalidLine(e) + "\n");
  }
}

main();

