import { type } from "arktype";
import { State, Event, type State as StateT, type Event as EventT } from "./schemas.js";

/**
 * Pure transition logic. Returns the *intended* next state for a valid
 * (state, event) pair, or the input state unchanged for any pair not
 * listed in the spec.
 *
 * The runtime validation of inputs/outputs lives in `transition` (below),
 * not here: this function is a plain implementation that *must* be invoked
 * through the validated wrapper so that malformed states/events are caught
 * at the boundary.
 */
export function transitionImpl(state: StateT, event: EventT): StateT {
  // `Reset` always returns `Idle`, irrespective of the current state.
  if (event.type === "reset") {
    return { status: "idle" };
  }

  if (state.status === "idle" && event.type === "start") {
    return {
      status: "loading",
      startedAt: Math.trunc(event.at),
    };
  }

  if (state.status === "loading" && event.type === "resolve") {
    return {
      status: "success",
      data: event.data,
      fetchedAt: Math.trunc(event.at),
    };
  }

  if (state.status === "loading" && event.type === "reject") {
    return {
      status: "failure",
      code: event.code,
      reason: event.reason,
    };
  }

  // Every other (state, event) pairing leaves the state unchanged.
  return state;
}

/**
 * `transition` - the public, runtime-validated transition function.
 *
 * Inputs are checked against `State` and `Event`, and the output is checked
 * against `State`. The implementation delegates to `transitionImpl`.
 *
 * Wrapped with `type.fn` so the contract is fully introspectable (`.params`,
 * `.returns`, `.expression`). `type.fn` throws a `TraversalError` whose
 * `.arkErrors` field carries the underlying `ArkErrors` when validation
 * fails; callers (e.g. `cli.ts`) translate that into the required stdout
 * format.
 */
export const transition = type.fn(State, Event, ":", State)(transitionImpl);

// Comprehensive test suite for the state machine

import { type } from "arktype";
import { transition } from "./src/transition.js";
import { State, Event } from "./src/schemas.js";

let pass = 0;
let fail = 0;

function eq(actual: unknown, expected: unknown, label: string) {
  const actualStr = JSON.stringify(actual);
  const expectedStr = JSON.stringify(expected);
  if (actualStr === expectedStr) {
    pass++;
    console.log(`PASS: ${label}`);
  } else {
    fail++;
    console.log(`FAIL: ${label}`);
    console.log(`  expected: ${expectedStr}`);
    console.log(`  actual:   ${actualStr}`);
  }
}

function isErr(result: unknown) {
  return result instanceof type.errors;
}

function errSummary(result: unknown) {
  if (result instanceof type.errors) return result.summary;
  return "";
}

// === Direct transition tests ===

// Idle + Start -> Loading
eq(
  transition({ status: "idle" }, { type: "start", at: 5 }),
  { status: "loading", startedAt: 5 },
  "idle + start -> loading",
);
// Idle + Start with float truncated
eq(
  transition({ status: "idle" }, { type: "start", at: 5.7 }),
  { status: "loading", startedAt: 5 },
  "idle + start -> loading (truncate)",
);

// Loading + Resolve -> Success
eq(
  transition({ status: "loading", startedAt: 0 }, { type: "resolve", data: { a: 1 }, at: 7 }),
  { status: "success", data: { a: 1 }, fetchedAt: 7 },
  "loading + resolve -> success",
);

// Loading + Reject -> Failure
eq(
  transition({ status: "loading", startedAt: 0 }, { type: "reject", code: 500, reason: "no", at: 0 }),
  { status: "failure", code: 500, reason: "no" },
  "loading + reject -> failure",
);

// Any state + Reset -> Idle
eq(
  transition({ status: "idle" }, { type: "reset" }),
  { status: "idle" },
  "idle + reset -> idle",
);
eq(
  transition({ status: "loading", startedAt: 0 }, { type: "reset" }),
  { status: "idle" },
  "loading + reset -> idle",
);
eq(
  transition({ status: "success", data: 1, fetchedAt: 0 }, { type: "reset" }),
  { status: "idle" },
  "success + reset -> idle",
);
eq(
  transition({ status: "failure", code: 400, reason: "x" }, { type: "reset" }),
  { status: "idle" },
  "failure + reset -> idle",
);

// Other combinations: state unchanged
eq(
  transition({ status: "idle" }, { type: "resolve", data: 1, at: 0 }),
  { status: "idle" },
  "idle + resolve -> idle (no change)",
);
eq(
  transition({ status: "success", data: 1, fetchedAt: 0 }, { type: "start", at: 5 }),
  { status: "success", data: 1, fetchedAt: 0 },
  "success + start -> success (no change)",
);

// === Validation tests ===
function expectError(label: string, fn: () => void, expected: string) {
  try {
    fn();
    fail++;
    console.log(`FAIL: ${label} (did not throw)`);
  } catch (e: any) {
    const s =
      e && typeof e === "object" && "arkErrors" in e
        ? (e.arkErrors?.summary ?? e.message)
        : e.message ?? String(e);
    if (s.includes(expected)) {
      pass++;
      console.log(`PASS: ${label}`);
    } else {
      fail++;
      console.log(`FAIL: ${label}`);
      console.log(`  expected to contain: ${expected}`);
      console.log(`  actual:              ${s}`);
    }
  }
}

expectError(
  "invalid state (bad status)",
  () => transition({ status: "garbage" } as any, { type: "reset" }),
  "idle",
);
expectError(
  "invalid state (missing startedAt)",
  () => transition({ status: "loading" } as any, { type: "reset" }),
  "startedAt",
);
expectError(
  "invalid state (loading - negative startedAt)",
  () => transition({ status: "loading", startedAt: -1 } as any, { type: "reset" }),
  "non-negative",
);
expectError(
  "invalid state (failure - bad code)",
  () => transition({ status: "failure", code: 200, reason: "x" } as any, { type: "reset" }),
  "400",
);
expectError(
  "invalid state (failure - short reason)",
  () => transition({ status: "failure", code: 500, reason: "" } as any, { type: "reset" }),
  "string",
);
expectError(
  "invalid event (bad type)",
  () => transition({ status: "idle" }, { type: "garbage" } as any),
  "",
);

expectError(
  "invalid output (Loading + Start -> Loading (truncated but negative))",
  () => transition({ status: "idle" }, { type: "start", at: -3.7 }),
  "non-negative",
);

// === Schema introspection tests ===

console.log("\nState branches:");
for (const expr of State.distribute((b) => b.expression)) {
  console.log(" ", expr);
}
console.log("\nEvent branches:");
for (const expr of Event.distribute((b) => b.expression)) {
  console.log(" ", expr);
}

console.log(`\n${pass} passed, ${fail} failed`);
if (fail > 0) process.exit(1);

